-- Update to the AFCD import adding 8 more micronutrients (magnesium,
-- zinc, vitamin A, vitamin C, vitamin B12, folate, polyunsaturated fat,
-- monounsaturated fat) used for the Pro micronutrient unlock. Upserts
-- onto the existing 1,588 rows from the original afcd_import.sql —
-- safe to run again even though the rows already exist.

on conflict (id) do update set
  name = excluded.name,
  calories = excluded.calories,
  protein_g = excluded.protein_g,
  carbs_g = excluded.carbs_g,
  fat_g = excluded.fat_g,
  fibre_g = excluded.fibre_g,
  sodium_mg = excluded.sodium_mg,
  sugar_g = excluded.sugar_g,
  magnesium_mg = excluded.magnesium_mg,
  zinc_mg = excluded.zinc_mg,
  vitamin_a_mcg = excluded.vitamin_a_mcg,
  vitamin_c_mg = excluded.vitamin_c_mg,
  vitamin_b12_mcg = excluded.vitamin_b12_mcg,
  folate_mcg = excluded.folate_mcg,
  polyunsaturated_fat_g = excluded.polyunsaturated_fat_g,
  monounsaturated_fat_g = excluded.monounsaturated_fat_g;

